#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

int main(int argc, char *argv[]) {
    // No input (no x provided)
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    // Only x provided, no coefficients
    if (argc == 2) {
        puts("EMPTY");
        return 0;
    }
    // Too many arguments: program name + x + >13 coefficients
    if (argc - 2 > 13) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    char *endptr;
    long x = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (x < -10 || x > 10) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    long long coeffs[13];
    for (int i = 0; i < argc - 2; ++i) {
        long val = strtol(argv[2 + i], &endptr, 10);
        if (endptr == argv[2 + i] || *endptr != '\0') {
            puts("BAD_INPUT");
            return 0;
        }
        if (val < -1000 || val > 1000) {
            puts("OUT_OF_RANGE");
            return 0;
        }
        coeffs[i] = val;
    }

    long long result = 0;
    for (int i = 0; i < argc - 2; ++i) {
        result = result * x + coeffs[i];
    }
    printf("%lld\n", result);
    return 0;
}
}
